package ingest

import (
	"errors"
	"testing"

	"replaycheck/internal/model"
)

// These tests run against fixtures generated by internal/fixtures. The import
// is intentionally absent until the fixture package lands; the build guard is
// the fixture package itself, so tests here only cover limits and scanning.

func TestScanLimits(t *testing.T) {
	dir := t.TempDir()
	path := writeTruncatedBox(t, dir)
	lim := DefaultLimits()
	_, err := ParseContainer(path, lim)
	if err == nil {
		t.Fatal("expected truncation error")
	}
	me, ok := model.AsError(err)
	if !ok {
		t.Fatalf("expected model error, got %v", err)
	}
	if me.Stage != model.StageIngest {
		t.Fatalf("stage=%s", me.Stage)
	}
	if me.Offset != 0 {
		t.Fatalf("offset=%d", me.Offset)
	}
}

func TestBackwardsErrorIsTyped(t *testing.T) {
	err := model.NewError(model.StageIngest, "test", model.TrackRef{ID: 2, Kind: "trak"}, 128, "x")
	var target *model.Error
	if !errors.As(err, &target) || target.Offset != 128 {
		t.Fatal("offset not preserved")
	}
}
